'use client';

import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { SettleItem } from '@/registry/ndeko/ui/settle';

import { SEED_ANCHOR, SEED_SECTION, type LightId } from './data';
import { LightChips } from './light-chips';
import {
  LOCK_PRESS_KEY,
  REPRODUCE_PRESS_KEY,
  SESSION,
  lightOf,
  lookOf,
  seedOf,
} from './light-session';
import { Reveal } from './reveal';
import { MugScene, TakeFrame } from './scenes';
import { SeedCard } from './seed-card';

export function LightAndSeed() {
  const { ref, isAutoplaying, state, act, pressed } = useSession(SESSION);
  const seed = seedOf(state);
  const light = lightOf(state.light);
  const announcement = `${light.label} light, seed ${seed}`;
  const message = spokenUnless(isAutoplaying, announcement);
  useKeptHeight(ref);

  function pickLight(next: LightId) {
    act({ type: 'lightPicked', light: next });
  }

  function toggleLock() {
    act({ type: 'lockToggled' });
  }

  function shuffle() {
    act({ type: 'shuffled' });
  }

  function reproduce() {
    act({ type: 'reproduced' });
  }

  return (
    <section
      id={SEED_ANCHOR}
      className='px-4 py-16 @sm:px-6 @sm:py-20 @5xl:px-8'
    >
      <Reveal
        className='mx-auto max-w-6xl'
        groupClassName='flex flex-col gap-8'
      >
        <SettleItem className='flex max-w-2xl flex-col gap-3'>
          <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
            {SEED_SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base text-pretty'>
            {SEED_SECTION.description}
          </p>
        </SettleItem>
        <SettleItem>
          <div
            ref={ref}
            className='bg-foreground/[0.03] grid min-h-[44rem] grid-cols-1 gap-2 rounded-2xl p-2 @3xl:min-h-[26rem] @3xl:grid-cols-[minmax(0,1fr)_minmax(0,1fr)] @3xl:gap-3 @3xl:p-3'
          >
            <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] flex flex-col gap-4 rounded-xl p-3 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
              <TakeFrame key={state.replay} state='ready' develops>
                <MugScene look={lookOf(state)} />
              </TakeFrame>
              <LightChips value={state.light} onValueChange={pickLight} />
            </div>
            <SeedCard
              light={state.light}
              seed={seed}
              isLocked={state.isLocked}
              isLockPressed={pressed === LOCK_PRESS_KEY}
              isReproducePressed={pressed === REPRODUCE_PRESS_KEY}
              onLockChange={toggleLock}
              onShuffle={shuffle}
              onReproduce={reproduce}
            />
            <LiveRegion message={message} />
          </div>
        </SettleItem>
      </Reveal>
    </section>
  );
}

'use client';

import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

import { LIGHTS, type LightId } from './data';

const CHIP =
  'h-7 rounded-full px-3 text-xs data-pressed:text-primary-ink data-pressed:ring-primary/50';

type LightChipsProps = {
  value: LightId;
  onValueChange: (light: LightId) => void;
};

export function LightChips({ value, onValueChange }: LightChipsProps) {
  const pressedValues = [value];

  function changeValue(nextValues: unknown[]) {
    const [nextValue] = nextValues;
    const light = LIGHTS.find((candidate) => candidate.id === nextValue);
    if (light) {
      onValueChange(light.id);
    }
  }

  return (
    <ToggleGroup
      aria-label='Lighting'
      value={pressedValues}
      onValueChange={changeValue}
      variant='outline'
      className='flex-wrap gap-1.5'
    >
      {LIGHTS.map((light) => (
        <ToggleGroupItem key={light.id} value={light.id} className={CHIP}>
          {light.label}
        </ToggleGroupItem>
      ))}
    </ToggleGroup>
  );
}

import type {
  SessionConfig,
  SessionStep,
} from '@/registry/ndeko/hooks/use-session';

import {
  DEFAULT_LIGHT,
  HERO_LOOKS,
  LIGHTS,
  SEED_LOOKS,
  SEED_SEQUENCE,
  type Light,
  type LightId,
  type SceneLook,
} from './data';

export type LightState = {
  light: LightId;
  seedIndex: number;
  isLocked: boolean;
  replay: number;
};

export type LightAction =
  | { type: 'lightPicked'; light: LightId }
  | { type: 'lockToggled' }
  | { type: 'shuffled' }
  | { type: 'reproduced' };

type Step = SessionStep<LightState, LightAction>;

export const LOCK_PRESS_KEY = 'lock';

export const REPRODUCE_PRESS_KEY = 'reproduce';

export const INITIAL: LightState = {
  light: DEFAULT_LIGHT,
  seedIndex: 0,
  isLocked: false,
  replay: 0,
};

export const RESTING: LightState = {
  light: DEFAULT_LIGHT,
  seedIndex: 0,
  isLocked: true,
  replay: 0,
};

function nextSeedIndexOf(seedIndex: number) {
  return (seedIndex + 1) % SEED_SEQUENCE.length;
}

function lightPicked(state: LightState, light: LightId): LightState {
  if (state.isLocked) {
    return { ...state, light };
  }
  return { ...state, light, seedIndex: nextSeedIndexOf(state.seedIndex) };
}

function shuffled(state: LightState): LightState {
  if (state.isLocked) {
    return state;
  }
  return { ...state, seedIndex: nextSeedIndexOf(state.seedIndex) };
}

export function reducer(state: LightState, action: LightAction): LightState {
  switch (action.type) {
    case 'lightPicked':
      return lightPicked(state, action.light);
    case 'lockToggled':
      return { ...state, isLocked: !state.isLocked };
    case 'shuffled':
      return shuffled(state);
    case 'reproduced':
      return { ...state, replay: state.replay + 1 };
  }
}

export function seedOf(state: LightState) {
  return SEED_SEQUENCE[state.seedIndex];
}

export function lightOf(id: LightId): Light {
  const found = LIGHTS.find((candidate) => candidate.id === id);
  return found ?? LIGHTS[0];
}

export function lookOf(state: LightState): SceneLook {
  const light = lightOf(state.light);
  const composition = SEED_LOOKS[state.seedIndex % SEED_LOOKS.length];
  return {
    ...HERO_LOOKS[0],
    ...light.look,
    mugX: composition.mugX,
    mugScale: composition.mugScale,
  };
}

function lightStep(after: number, light: LightId): Step {
  return { after, by: 'demo', action: { type: 'lightPicked', light } };
}

