const DEFAULT_READY_MS = 800;

function takeStateOf(state: StudioState, index: number): TakeState {
  if (state.stage === 'typing') {
    return 'idle';
  }
  if (index < state.readyCount) {
    return 'ready';
  }
  return 'developing';
}

function statusOf(state: StudioState) {
  if (state.stage === 'making') {
    const current = state.readyCount + 1;
    return `Developing take ${current} of ${TAKE_COUNT}`;
  }
  if (state.stage === 'done') {
    return `${TAKE_COUNT} takes ready`;
  }
  return `${TAKE_COUNT} takes per brief`;
}

function seedToneOf(isReady: boolean) {
  if (isReady) {
    return 'opacity-100';
  }
  return 'opacity-0';
}

export function StudioCard() {
  const { ref, isInView, isAutoplaying, state, act, pressed } =
    useSession(SESSION);
  const briefId = useId();
  const isMaking = state.stage === 'making';
  const hasBrief = state.brief.trim() !== '';
  const canMake = hasBrief && !isMaking;
  const isMakePressed = pressed === MAKE_PRESS_KEY;
  const status = statusOf(state);
  const message = spokenUnless(isAutoplaying, status);
  useKeptHeight(ref);

  useEffect(() => {
    if (!isMaking || !isInView) {
      return;
    }
    const delay = READY_DELAYS_MS[state.readyCount] ?? DEFAULT_READY_MS;
    const timer = setTimeout(() => act({ type: 'takeReady' }), delay);
    return () => clearTimeout(timer);
  }, [isMaking, isInView, state.readyCount, act]);

  function type(event: React.ChangeEvent<HTMLTextAreaElement>) {
    act({ type: 'typed', text: event.target.value });
  }

  function make() {
    act({ type: 'made' });
  }

  return (
    <div
      ref={ref}
      className='bg-foreground/[0.03] @container/studio min-h-[34rem] rounded-2xl p-2 @sm/studio:p-3'
    >
      <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] flex flex-col gap-4 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
        <div className='flex flex-col gap-2'>
          <Label htmlFor={briefId}>Brief</Label>
          <Textarea
            id={briefId}
            value={state.brief}
            onChange={type}
            placeholder='Describe the shot'
            className='min-h-[5rem]'
          />
        </div>
        <div className='flex flex-wrap items-center gap-3'>
          <Button
            size='lg'
            disabled={!canMake}
            onClick={make}
            className={pressedSolidOf(isMakePressed)}
          >
            {MAKE_LABEL}
          </Button>
          <p className='text-muted-foreground text-xs tabular-nums'>
            <Swap swapKey={status}>{status}</Swap>
          </p>
        </div>
        <ul className='grid grid-cols-2 gap-2'>
          {HERO_TAKES.map((take, index) => {
            const takeState = takeStateOf(state, index);
            const isReady = takeState === 'ready';
            return (
              <li key={take.id} className='flex flex-col gap-1.5'>
                <TakeFrame state={takeState}>
                  <MugScene look={HERO_LOOKS[index]} />
                </TakeFrame>
                <div className='flex items-center justify-between gap-2 text-xs'>
                  <span className='text-muted-foreground'>
                    Take {index + 1}
                  </span>
                  <Badge
                    variant='secondary'
                    className={cn(
                      'tabular-nums transition-opacity duration-300',
                      seedToneOf(isReady)
                    )}
                  >
                    {take.seed}
                  </Badge>
                </div>
              </li>
            );
          })}
        </ul>
      </div>
      <LiveRegion message={message} />
    </div>
  );
}

import type {
  SessionConfig,
  SessionStep,
} from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

import { BRIEF, HERO_TAKES } from './data';

export type StudioStage = 'typing' | 'making' | 'done';

export type StudioState = {
  brief: string;
  stage: StudioStage;
  readyCount: number;
};

export type StudioAction =
  | { type: 'typed'; text: string }
  | { type: 'made' }
  | { type: 'takeReady' }
  | { type: 'settled' };

type Step = SessionStep<StudioState, StudioAction>;

export const TAKE_COUNT = HERO_TAKES.length;

export const MAKE_PRESS_KEY = 'make';

export const READY_DELAYS_MS = [1100, 800, 650, 900];

export const INITIAL: StudioState = {
  brief: '',
  stage: 'typing',
  readyCount: 0,
};

export const RESTING: StudioState = {
  brief: BRIEF,
  stage: 'done',
  readyCount: TAKE_COUNT,
};

function made(state: StudioState): StudioState {
  const isEmpty = state.brief.trim() === '';
  if (isEmpty || state.stage === 'making') {
    return state;
  }
  return { ...state, stage: 'making', readyCount: 0 };
}

function takeReady(state: StudioState): StudioState {
  if (state.stage !== 'making') {
    return state;
  }
  const readyCount = state.readyCount + 1;
  if (readyCount >= TAKE_COUNT) {
    return { ...state, stage: 'done', readyCount };
  }
  return { ...state, readyCount };
}

export function reducer(state: StudioState, action: StudioAction) {
  switch (action.type) {
    case 'typed':
      return { ...state, brief: action.text };
    case 'made':
      return made(state);
    case 'takeReady':
      return takeReady(state);
    case 'settled':
      return state;
  }
}

function hasMade(state: StudioState) {
  return state.stage !== 'typing';
}

function isMaking(state: StudioState) {
  return state.stage === 'making';
}

function typingSteps() {
  const prefixes = prefixesOf(BRIEF);
  return prefixes.map((text, index): Step => {
    const after = keyDelayOf(index, 1000, 38);
    return { after, by: 'demo', action: { type: 'typed', text } };
  });
}

const SCRIPT: Step[] = [
  ...typingSteps(),
  {
    after: 700,
    by: 'person',
    press: MAKE_PRESS_KEY,
    action: { type: 'made' },
    isAnswered: hasMade,
  },
  { after: 500, by: 'agent', action: { type: 'settled' } },
];

export const SESSION: SessionConfig<StudioState, StudioAction> = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: 3600,
  holdWhile: isMaking,
};

import type {
  SessionConfig,
  SessionStep,
} from '@/registry/ndeko/hooks/use-session';

import { LANES, TRIAGE_TAKES, type Lane, type SubjectId } from './data';

export type TriageState = {
  lanes: Record<Lane, SubjectId[]>;
  lastMove: string;
};

export type TriageAction =
  | { type: 'sorted'; id: SubjectId; lane: Lane }
  | { type: 'returned'; id: SubjectId }
  | { type: 'cleared' };

type Step = SessionStep<TriageState, TriageAction>;

export const INITIAL: TriageState = {
  lanes: { keep: [], maybe: [], drop: [] },
  lastMove: '',
};

export const RESTING: TriageState = {
  lanes: {
    keep: ['mug', 'hills', 'bowl'],
    maybe: ['plant', 'window'],
    drop: ['bottles'],
  },
  lastMove: '',
};

export function titleOf(id: SubjectId) {
  const take = TRIAGE_TAKES.find((candidate) => candidate.id === id);
  if (!take) {
    return id;
  }
  return take.title;
}

export function laneLabelOf(lane: Lane) {
  const found = LANES.find((candidate) => candidate.id === lane);
  if (!found) {
    return lane;
  }
  return found.label;
}

export function takesIn(state: TriageState, lane: Lane) {
  const ids = state.lanes[lane];
  return TRIAGE_TAKES.filter((take) => ids.includes(take.id));
}

export function unsortedOf(state: TriageState) {
  const sorted = [
    ...state.lanes.keep,
    ...state.lanes.maybe,
    ...state.lanes.drop,
  ];
  return TRIAGE_TAKES.filter((take) => !sorted.includes(take.id));
}

function withoutTake(lanes: Record<Lane, SubjectId[]>, id: SubjectId) {
  return {
    keep: lanes.keep.filter((taken) => taken !== id),
    maybe: lanes.maybe.filter((taken) => taken !== id),
    drop: lanes.drop.filter((taken) => taken !== id),
  };
}

function sorted(state: TriageState, id: SubjectId, lane: Lane): TriageState {
  const lanes = withoutTake(state.lanes, id);
  lanes[lane] = [...lanes[lane], id];
  const lastMove = `${titleOf(id)} moved to ${laneLabelOf(lane)}`;
  return { lanes, lastMove };
}

export function reducer(state: TriageState, action: TriageAction): TriageState {
  switch (action.type) {
    case 'sorted':
      return sorted(state, action.id, action.lane);
    case 'returned':
      return {
        lanes: withoutTake(state.lanes, action.id),
        lastMove: `${titleOf(action.id)} moved back to unsorted`,
      };
    case 'cleared':
      return INITIAL;
  }
}

export function sortPressKeyOf(id: SubjectId, lane: Lane) {
  return `${id}:${lane}`;
}

const FIRST_SORT_MS = 1400;

const SORT_MS = 950;

function sortStep(after: number, id: SubjectId, lane: Lane): Step {
  return {
    after,
    by: 'demo',
    press: sortPressKeyOf(id, lane),
    action: { type: 'sorted', id, lane },
  };
}

const SCRIPT: Step[] = [
  sortStep(FIRST_SORT_MS, 'mug', 'keep'),
  sortStep(SORT_MS, 'bottles', 'drop'),
  sortStep(SORT_MS, 'plant', 'maybe'),
  sortStep(SORT_MS, 'hills', 'keep'),
  sortStep(SORT_MS, 'window', 'maybe'),
  sortStep(SORT_MS, 'bowl', 'keep'),
];

export const SESSION: SessionConfig<TriageState, TriageAction> = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: 2800,
};

